{
    "name": "007_hyena_fft_size_padding_rfft",
    "hf_id": "LongSafari/hyenadna-small-32k-seqlen-hf",
    "description": "Fused FFT size padding and real FFT computation for Hyena convolution. Pads input to 2*seqlen for circular convolution, computes real FFT (rfft), and normalizes by fft_size. Input is (batch, channels, seqlen) and output is complex tensor (batch, channels, seqlen+1) in frequency domain.",
    "axes": {
        "batch_size": {
            "type": "var",
            "description": "Batch size"
        },
        "d_model": {
            "type": "const",
            "value": 256,
            "description": "Number of channels/model dimension"
        },
        "seqlen": {
            "type": "var",
            "description": "Sequence length"
        },
        "freq_len": {
            "type": "expr",
            "expression": "seqlen + 1",
            "description": "Output frequency domain length (seqlen+1 for rfft)"
        }
    },
    "custom_inputs_entrypoint": null,
    "inputs": {
        "x": {
            "shape": [
                "batch_size",
                "d_model",
                "seqlen"
            ],
            "dtype": "float32",
            "description": "Input tensor (either input signal u or filter kernel k)"
        }
    },
    "outputs": {
        "x_freq_real": {
            "shape": [
                "batch_size",
                "d_model",
                "freq_len"
            ],
            "dtype": "float32",
            "description": "Real part of normalized frequency domain output"
        },
        "x_freq_imag": {
            "shape": [
                "batch_size",
                "d_model",
                "freq_len"
            ],
            "dtype": "float32",
            "description": "Imaginary part of normalized frequency domain output"
        }
    },
    "reference": "import torch\n\n@torch.no_grad()\ndef run(x: torch.Tensor):\n    \"\"\"\n    Fused FFT size padding and real FFT computation for Hyena convolution.\n    \n    Args:\n        x: Input tensor of shape (batch, channels, seqlen)\n        \n    Returns:\n        x_freq_real: Real part of normalized frequency domain output (batch, channels, seqlen+1)\n        x_freq_imag: Imaginary part of normalized frequency domain output (batch, channels, seqlen+1)\n    \"\"\"\n    batch, channels, seqlen = x.shape\n    fft_size = 2 * seqlen\n    \n    # Cast to float32 for FFT numerical stability (already float32 but explicit)\n    x_f32 = x.to(torch.float32)\n    \n    # Perform real FFT with implicit zero-padding to fft_size\n    # Output shape: (batch, channels, seqlen+1) complex\n    x_freq = torch.fft.rfft(x_f32, n=fft_size)\n    \n    # Normalize by fft_size\n    x_freq = x_freq / fft_size\n    \n    # Return real and imaginary parts separately since we can't have complex dtype in outputs\n    x_freq_real = x_freq.real.contiguous()\n    x_freq_imag = x_freq.imag.contiguous()\n    \n    return x_freq_real, x_freq_imag\n"
}

